@@ -375,6 +375,8 @@ int libssh2_knownhost_addc(LIBSSH2_KNOWNHOSTS *hosts,
  * LIBSSH2_KNOWNHOST_CHECK_MATCH
  * LIBSSH2_KNOWNHOST_CHECK_MISMATCH
  */
+#define LIBSSH2_KNOWNHOST_IPV6_WORDS 8
+
 static int knownhost_hex_value(char c)
 {
     if(c >= '0' && c <= '9')
@@ -422,7 +424,7 @@ static int knownhost_parse_ipv4(const char *src, const char *end,
 static int knownhost_parse_ipv6(const char *src, size_t len,
                                 unsigned char result[16])
 {
-    unsigned short words[8];
+    unsigned short words[LIBSSH2_KNOWNHOST_IPV6_WORDS];
     const char *p = src;
     const char *end = src + len;
     size_t count = 0;
@@ -458,7 +460,8 @@ static int knownhost_parse_ipv6(const char *src, size_t len,
         if(p < end && *p == '.') {
             unsigned char ipv4[4];

-            if(count > 6 || !knownhost_parse_ipv4(part, end, ipv4))
+            if(count > LIBSSH2_KNOWNHOST_IPV6_WORDS - 2 ||
+               !knownhost_parse_ipv4(part, end, ipv4))
                 return 0;

             words[count++] =
@@ -468,7 +471,7 @@ static int knownhost_parse_ipv6(const char *src, size_t len,
             break;
         }

-        if(!digits || count >= 8)
+        if(!digits || count >= LIBSSH2_KNOWNHOST_IPV6_WORDS)
             return 0;

         words[count++] = (unsigned short)value;
@@ -495,18 +498,18 @@ static int knownhost_parse_ipv6(const char *src, size_t len,
         size_t position = (size_t)compressed;
         size_t zeros;

-        if(count >= 8)
+        if(count >= LIBSSH2_KNOWNHOST_IPV6_WORDS)
             return 0;

-        zeros = 8 - count;
+        zeros = LIBSSH2_KNOWNHOST_IPV6_WORDS - count;
         memmove(&words[position + zeros], &words[position],
                 (count - position) * sizeof(words[0]));
         memset(&words[position], 0, zeros * sizeof(words[0]));
     }
-    else if(count != 8)
+    else if(count != LIBSSH2_KNOWNHOST_IPV6_WORDS)
         return 0;

-    for(i = 0; i < 8; i++) {
+    for(i = 0; i < LIBSSH2_KNOWNHOST_IPV6_WORDS; i++) {
         result[i * 2] = (unsigned char)(words[i] >> 8);
         result[i * 2 + 1] = (unsigned char)words[i];
     }

